using System;
using System.IO;
using System.Reflection;
using System.Threading;
namespace Downfield {
public static class AudioTests {
 static int checks,failures;static void Check(bool ok,string name){checks++;if(!ok){failures++;Console.WriteLine("FAIL Audio: "+name);}}
 static double Energy(short[] samples){double energy=0;foreach(short sample in samples)energy+=(double)sample*sample;return Math.Sqrt(energy/Math.Max(1,samples.Length));}
 static short[] Render(StadiumMixer mixer,int frames){short[] samples=new short[frames*2];mixer.Render(samples,frames);return samples;}
 static void Invoke(Simulation s,string method,params object[] args){typeof(Simulation).GetMethod(method,BindingFlags.NonPublic|BindingFlags.Instance,null,Array.ConvertAll(args,a=>a.GetType()),null).Invoke(s,args);}
 public static int Run(){checks=failures=0;
  foreach(string cue in new string[]{"ambience","crowd_cheer","crowd_big","crowd_first","crowd_groan","hit","truck","whistle","horn"}){float[] samples=FootballSounds.Get(cue);float peak=0;double energy=0;foreach(float sample in samples){peak=Math.Max(peak,Math.Abs(sample));energy+=sample*sample;}Check(samples.Length>2000&&energy/samples.Length>.0001&&peak<=1,"audible bounded clip "+cue);}
  StadiumMixer mix=new StadiumMixer();Check(Energy(Render(mix,512))==0,"menus start quiet");mix.Stadium=true;Render(mix,FootballSounds.Rate);short[] bed=Render(mix,FootballSounds.Rate);Check(Energy(bed)>100,"steady crowd during games");mix.Stadium=false;Render(mix,FootballSounds.Rate*3);Check(Energy(Render(mix,512))<1,"leaving field fades ambience");
  StadiumMixer hit=new StadiumMixer(),both=new StadiumMixer(),whistle=new StadiumMixer();hit.Play("hit");both.Play("hit");both.Play("whistle");whistle.Play("whistle");Check(both.VoiceCount==2,"hit and whistle coexist");short[] impact=Render(hit,1000),combined=Render(both,1000);bool equal=true;for(int i=0;i<impact.Length;i++)if(impact[i]!=combined[i])equal=false;Check(equal&&Energy(combined)>100,"whistle never replaces initial impact");Render(both,2000);Check(both.VoiceCount>0&&Energy(Render(both,300))>0,"delayed whistle is audible after impact");Check(Energy(Render(whistle,1000))==0,"whistle delay gives contact room");
  mix=new StadiumMixer();mix.Stadium=true;mix.Play("score");mix.Play("whistle");Check(mix.VoiceCount==3,"touchdown cheer horn and whistle overlap");short[] celebration=Render(mix,FootballSounds.Rate*2);Check(Energy(celebration)>Energy(bed)*1.5,"touchdown is louder than ambient crowd");int count=mix.VoiceCount;mix.Play("crowd_first");Check(mix.VoiceCount==count,"small play cannot cut off touchdown cheer");Render(mix,FootballSounds.Rate*4);Check(mix.VoiceCount==0,"events expire without leaking voices");
  mix.Play("truck");short[] stereo=Render(mix,1000);bool spatial=false;foreach(int i in new int[]{100,400,700})if(stereo[i*2]!=stereo[i*2+1])spatial=true;Check(spatial,"contact has stereo width");for(int i=0;i<80;i++)mix.Play(i%2==0?"crowd_big":"hit");Check(mix.VoiceCount<=16,"bursts keep bounded voice count");short[] loud=Render(mix,FootballSounds.Rate);int peakMixed=0;foreach(short sample in loud)peakMixed=Math.Max(peakMixed,Math.Abs((int)sample));Check(peakMixed>100&&peakMixed<30000,"simultaneous sounds stay below clipping");
  mix.Muted=true;mix.Play("score");Check(mix.VoiceCount==0&&Energy(Render(mix,1000))==0,"mute silences all channels and queued reactions");mix.Muted=false;mix.Play("hit");mix.Suspended=true;Check(Energy(Render(mix,1000))==0&&mix.VoiceCount==0,"focus loss silences and clears effects");mix.Suspended=false;mix.Play("hit");Check(Energy(Render(mix,1000))>0,"returning focus restores effects");mix.Volume=0;Check(Energy(Render(mix,1000))==0,"zero master gain is silent");
  float[] ambient=FootballSounds.Get("ambience");Check(Math.Abs(ambient[ambient.Length-1]-ambient[FootballSounds.Rate/4])<.025f,"ambient loop seam is smooth");Check(ambient.Length>=FootballSounds.Rate*30,"background no longer repeats a short stadium snippet");double movement=0,totalEnergy=0;for(int i=1;i<ambient.Length;i++){movement+=(ambient[i]-ambient[i-1])*(ambient[i]-ambient[i-1]);totalEnergy+=ambient[i]*ambient[i];}Check(movement/Math.Max(.0001,totalEnergy)<.1,"background excludes piercing high-frequency whistles");float[] ending=FootballSounds.Get("whistle");double lowTone=0,highTone=0;foreach(int frequency in new int[]{180,3050}){double real=0,imaginary=0;for(int i=0;i<ending.Length;i++){double phase=2*Math.PI*frequency*i/FootballSounds.Rate;real+=ending[i]*Math.Cos(phase);imaginary+=ending[i]*Math.Sin(phase);}if(frequency==180)lowTone=real*real+imaginary*imaginary;else highTone=real*real+imaginary*imaginary;}Check(highTone<lowTone*.02,"legacy whistle cue is now a soft low play-ending sound");
  Check(Energy(bed)<600,"background crowd stays quiet instead of dominating play");double low=double.MaxValue,high=0;float[] cheer=FootballSounds.Get("crowd_cheer");for(int start=FootballSounds.Rate/4;start+FootballSounds.Rate/4<cheer.Length;start+=FootballSounds.Rate/4){double energy=0;for(int n=0;n<FootballSounds.Rate/4;n++)energy+=cheer[start+n]*cheer[start+n];low=Math.Min(low,energy);high=Math.Max(high,energy);}Check(high>low*2,"recorded cheer has natural changes in energy");
  foreach(string name in new string[]{"stadium","cheer","applause","groan"}){float[] recording=CrowdRecordings.Read(name);Check(recording.Length>FootballSounds.Rate*2,"recorded crowd is embedded in standalone EXE: "+name);}
  Simulation s=new Simulation(12);s.Sounds.Clear();Invoke(s,"ScoreTouchdown");Check(s.Sounds.Contains("score"),"touchdown triggers stadium celebration");s=new Simulation(12);s.Sounds.Clear();Invoke(s,"EndPlay",35f,"TACKLED",false);Check(s.Sounds.Contains("crowd_first")&&s.Sounds.Contains("whistle"),"first down gets applause and whistle");s=new Simulation(12);s.Sounds.Clear();Invoke(s,"BeginOpponent",new object[]{"INTERCEPTED BY #24",false});Check(s.Sounds.Contains("crowd_groan"),"turnover gets crowd disappointment");s=new Simulation(12);s.Sounds.Clear();s.Quarter=4;s.Clock=0;s.HomeScore=21;Invoke(s,"CheckQuarter");Check(s.Sounds.Contains("crowd_cheer")&&s.Sounds.Contains("whistle"),"winning final whistle celebrates");
  s=new Simulation(12);s.Spot=80;s.FieldGoal();s.KickMeter=1;s.StopKick();s.Sounds.Clear();for(int i=0;i<44;i++)s.Update(.05f,0,0);Check(s.Sounds.Contains("crowd_groan"),"missed field goal gets crowd reaction");
  Console.WriteLine("Audio: "+checks+" checks, "+failures+" failures");return failures;
 }
 public static int Smoke(){using(GameAudio sound=new GameAudio()){Console.WriteLine("Windows audio devices: "+WaveOutput.DeviceCount+"; opened="+sound.OutputAvailable+"; error="+sound.OutputError);if(!sound.OutputAvailable)return 2;sound.SetContext(true,true);Thread.Sleep(500);sound.Play("hit");sound.Play("crowd_big");sound.Play("whistle");Thread.Sleep(1200);sound.Play("score");Thread.Sleep(2500);Console.WriteLine("Submitted audio buffers: "+sound.WrittenBuffers);return sound.OutputAvailable&&sound.WrittenBuffers>30?0:1;}}
 public static void Preview(string path){StadiumMixer mixer=new StadiumMixer();mixer.Stadium=true;int frames=FootballSounds.Rate*12;float[] mono=new float[frames];for(int second=0;second<12;second++){if(second==1)mixer.Play("snap");if(second==2){mixer.Play("hit");mixer.Play("crowd_big");mixer.Play("whistle");}if(second==5)mixer.Play("score");if(second==10)mixer.Play("crowd_groan");short[] audio=Render(mixer,FootballSounds.Rate);for(int i=0;i<FootballSounds.Rate;i++)mono[second*FootballSounds.Rate+i]=(audio[i*2]+audio[i*2+1])/65534f;}File.WriteAllBytes(path,FootballSounds.Wave(mono));}
}
}
